components.css:
.ds-preview-drive-button{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);color:var(--ink,#122d38);background:var(--paper,#f6f1e4)}.ds-preview-drive-button button{font:inherit;cursor:pointer}.ds-preview-drive-button button:disabled{cursor:default;opacity:.45}.ds-preview-drive-button button:focus-visible{outline:2px solid currentColor;outline-offset:4px}.ds-preview-drive-button svg{width:1.25rem;height:1.25rem;flex-shrink:0}
.ds-drive-button { display: inline-flex; align-items: center; justify-content: center; gap: 0.6rem; min-height: 3.25rem; border-radius: 2px; padding: 0.65rem 1rem; border: 1px solid var(--ink, #122d38); color: var(--ink, #122d38); background: transparent; font-size: 0.9375rem; font-weight: 600; }
.ds-drive-button { min-width: 9.5rem; border-color: var(--ink, #122d38); background: var(--ink, #122d38); color: var(--paper, #f6f1e4); }
.ds-drive-button:hover { background: #294954; }
.ds-drive-button[aria-pressed="true"] { background: var(--signal, #f2cb75); color: var(--ink, #122d38); }

.ds-preview-autoplay{font-family:var(--sans,-apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);color:var(--paper,#f6f1e4);background:var(--night,#081d29)}.ds-preview-autoplay button{font:inherit;cursor:pointer}.ds-preview-autoplay button:focus-visible{outline:2px solid currentColor;outline-offset:4px}
.ds-quiet-button { min-height: 2.75rem; border: 0; padding: 0.5rem 0.75rem; color: inherit; background: transparent; font-size: 0.875rem; }
.ds-quiet-button:hover { color: var(--signal, #f2cb75); }
.ds-autoplay-button { border: 1px solid var(--signal, #f2cb75); color: var(--signal, #f2cb75); min-width: 5.5rem; }
.ds-autoplay-button[aria-pressed="true"] { background: var(--signal, #f2cb75); color: var(--ink, #122d38); }

.ds-place-strip { display: grid; grid-template-columns: repeat(23, minmax(0, 1fr)); gap: 0.25rem; padding: 0.5rem 1.5rem; background: var(--night, #081d29); border-bottom: 1px solid var(--line, #3b5965); }
.ds-place-button { min-width: 0; min-height: 1.75rem; padding: 0.25rem 0.15rem; border: 1px solid transparent; color: var(--muted, #a9c0c8); background: transparent; font: 500 0.75rem/1.25 var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif); overflow-wrap: anywhere; }
.ds-place-button:hover { border-color: var(--line, #3b5965); color: var(--paper, #f6f1e4); }
.ds-place-button[aria-current="location"] { color: var(--ink, #122d38); background: var(--signal, #f2cb75); border-color: var(--signal, #f2cb75); text-decoration: none; font-weight: 700; }
.ds-place-strip button{cursor:pointer}.ds-place-strip button:focus-visible{outline:2px solid currentColor;outline-offset:4px}@media(max-width:100rem){.ds-place-strip{grid-template-columns:repeat(12,minmax(0,1fr))}}@media(max-width:56rem){.ds-place-strip{grid-template-columns:repeat(8,minmax(0,1fr))}}@media(max-width:37.5rem){.ds-place-strip{grid-template-columns:repeat(6,minmax(0,1fr))}}
@media(max-width:37.5rem) and (max-height:37.5rem){.ds-place-strip{display:flex;flex-wrap:wrap;gap:2px;padding:4px 12px}.ds-place-button,html[lang="en"] .ds-place-button{flex:0 0 auto;min-width:24px;min-height:24px;padding:2px;font-size:12px;line-height:1.2;white-space:nowrap;overflow-wrap:normal}}

.ds-preview-arrival-note{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);color:var(--ink,#122d38);background:var(--paper,#f6f1e4)}.ds-preview-arrival-note button{font:inherit;cursor:pointer}.ds-preview-arrival-note button:disabled{cursor:default;opacity:.45}.ds-preview-arrival-note button:focus-visible{outline:2px solid currentColor;outline-offset:4px}.ds-preview-arrival-note svg{width:1.25rem;height:1.25rem;flex-shrink:0}
.ds-arrival-note { position: absolute; top: 43%; right: 2.5rem; width: min(18rem, 34%); padding: 1.25rem 1.5rem; z-index: 1; color: var(--ink, #122d38); background: var(--paper, #f6f1e4); border-radius: 2px; box-shadow: 0 10px 28px rgb(0 0 0 / 18%); }
.ds-arrival-note h3 { font: 600 1.25rem/1.6 var(--serif, "Songti SC", "STSong", Georgia, serif); margin-bottom: 0.85rem; }
.ds-text-button { background: transparent; border: 0; border-bottom: 1px solid currentColor; padding: 0.4rem 0; min-height: 2.75rem; color: inherit; font-size: 0.875rem; }
.ds-arrival-note{position:relative;top:auto;right:auto;width:min(18rem,100%)}

.ds-preview-modal{font-family:var(--sans, -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif);color:var(--ink,#122d38);background:var(--paper,#f6f1e4)}.ds-preview-modal button{font:inherit;cursor:pointer}.ds-preview-modal button:disabled{cursor:default;opacity:.45}.ds-preview-modal button:focus-visible{outline:2px solid currentColor;outline-offset:4px}.ds-preview-modal svg{width:1.25rem;height:1.25rem;flex-shrink:0}
.ds-modal-footer { display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-width: 0; }
.ds-page-controls { display: flex; align-items: center; gap: 0.5rem; }
.ds-page-controls button { width: 2.75rem; min-height: 2.75rem; display: grid; place-items: center; background: transparent; color: var(--ink, #122d38); border: 1px solid var(--ink, #122d38); }
.ds-page-controls button:hover:enabled { background: var(--signal, #f2cb75); }
.ds-page-count { color: var(--muted-ink, #51616a); font-size: 0.875rem; font-variant-numeric: tabular-nums; }
.ds-reader-close { border: 0; background: none; color: var(--ink, #122d38); padding: 0.5rem 0; min-height: 2.75rem; font-size: 0.875rem; text-decoration: underline; text-underline-offset: 0.2em; }
